D.Quests[28801]={Title="托维尔符文"}
D.Quests[28802]={Title="建筑师的地图"}
D.Quests[28803]={Title="蛮锤的复仇"}
D.Quests[28804]={Title="黑铁矮人的防范计划"}
D.Quests[28805]={Title="风暴之眼",Objectives="先知克洛伽要你观察先知之水中的景象。",Description="你好，$n。$b$b你在大地之环中可说是声名显赫。$b$b你的功绩和成就数不胜数。你已经为艾泽拉斯做了许多，但现在她又一次向她的英雄们发出了召唤。$b$b我只不过是一名信使。一位熟悉的存在想与你会面。$b$b去看一眼先知之水，亲眼看看我们的世界所面临的命运吧。"}
D.Quests[28806]={Title=S[3614],Objectives=S[18559],Description=S[1784]}
D.Quests[28807]={Title="专家意见",Objectives=S[12016],Description="<安度因拿起匹配的徽章。>$B$B我们在农场发现的徽章和在萨缪尔森的档案堆里找到那个一样！这不可能是个巧合。我认为萨缪尔森在谋划什么，但在指控父王最信任的守卫之前，我们需要如山的铁证。$B$B我只相信一个人能把事情办妥：马迪亚斯·肖尔，军情七处处长。把徽章拿给他看，听听他怎么说。同时，我会回到城堡，盯着萨缪尔森！",CompletionLog=S[12016]}
D.Quests[28808]={Title=S[3614],Objectives=S[18559],Description=S[1784]}
